mod solution;

fn main() {
    let cases = [
    (r#"[2, 1, 2, 3, 2, 2, 4]"#, r#"2"#),
    (r#"[7, 7, 2]"#, r#"7"#),
    (r#"
[7, 7, 2]
"#, r#"7"#),
    (r#"  
[2, 1, 2, 3, 2, 2, 4]
  "#, r#"2"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS boyer-moore-majority");
}
